// The spoken narration of the tour: what is said and when (seconds from the start of the video).
// The text is generated by VoiceStudio (see tools/narrate.ts) into public/narration/<id>.wav.
// This file has no imports, so both the video and the generator script can read it.

export interface NarrationLine {
  id: string;
  /** Start in the video, seconds. */
  at: number;
  /** What is said; written so that it is pronounced right (e.g. "Control K", not "Ctrl+K"). */
  text: string;
  /** Speed of the speech, 1 = normal; used to fit a line into the time it has. */
  speed?: number;
}

export const VOICE = {
  /** The English demo voice that comes with VoiceStudio (profile id). */
  profile: "demo0001",
  language: "en",
  /** The same seed and text give the same speech, so a re-render does not change the voice. */
  seed: 7,
};

